import { create } from "zustand";
import { useShallow } from "zustand/react/shallow";

type ListUiState = {
  filter: "all" | "open" | "done";
  sidebarOpen: boolean;
  setFilter: (filter: ListUiState["filter"]) => void;
  toggleSidebar: () => void;
};

export const useListUi = create<ListUiState>()((set) => ({
  filter: "all",
  sidebarOpen: false,
  setFilter: (filter) => set({ filter }),               // shallow-merged into state
  toggleSidebar: () => set((s) => ({ sidebarOpen: !s.sidebarOpen })),
}));

// Subscribe to a slice: this component re-renders only when filter changes.
const filter = useListUi((s) => s.filter);
// Several values: useShallow compares the picked object key by key.
const { filter: f, sidebarOpen } = useListUi(useShallow((s) => ({ filter: s.filter, sidebarOpen: s.sidebarOpen })));
